($f$080b7013-14b2-4fd8-be8b-f567db3cdb39$f$, 19762102, $f$The Moon-Edged Roof of Paradise$f$, ARRAY[$f$Gileonnen$f$]::text[], ARRAY[$f$天官赐福 - 墨香铜臭 | Tiān Guān Cì Fú - Mòxiāng Tóngxiù$f$]::text[], NULL, ARRAY[]::text[], $f$Beyond Heaven's walls, Xie Lian finds himself learning to feel at home in the Ghost City--and in Hua Cheng's arms.$f$, 1444, 1, 1, true, 5, false, $f$2019-10-12T22:44:06.196+00:00$f$, $f$2019-10-12T22:44:06.224+00:00$f$, $f$2019-07-11T00:00:00.000+00:00$f$, false, false, true, NULL, NULL, ARRAY[]::text[]),
($f$080b7013-14b2-4fd8-be8b-f567db3cdb39$f$, 19769164, $f$blessings of a white flower$f$, ARRAY[$f$RennieOnIceCream (Hitsugi_Zirkus)$f$]::text[], ARRAY[$f$天官赐福 - 墨香铜臭 | Tiān Guān Cì Fú - Mòxiāng Tóngxiù$f$]::text[], NULL, ARRAY[]::text[], $f$Hua Cheng smirked. “I don’t know if that’s guaranteed. Gege already made such a mess of me.”“...I can make an even bigger mess of you.”The boldness and promise held in that velvet-sweet voice sent a bolt of anticipation right down Hua Cheng’s spine.---In which Xie Lian's body has some interesting reactions after 800 years of abstinence and Hua Cheng is more than happy to take the edge off for him.$f$, 7440, 1, 1, true, 5, false, $f$2019-10-13T21:39:50.225+00:00$f$, $f$2019-10-13T21:39:50.420+00:00$f$, $f$2019-07-11T00:00:00.000+00:00$f$, false, false, true, NULL, NULL, ARRAY[]::text[]),
